    QUANTITY           ,  -- is_other_attr
    RECRUITERFEE       ,  -- is_other_attr
    SALESTAXAMOUNT     ,  -- is_other_attr
    SALESTAXBASISAMOUNT,  -- is_other_attr
    SALESTAXID         ,  -- is_other_attr
    SALESTAXPERCENTAGE ,  -- is_other_attr
    VMSBURDENAMOUNT    ,  -- is_other_attr
